<template>
  <section class="app-listing">
    <h1 class="app-listing__title section-title">{{ title }}</h1>

    <div :class="listClass">
      <slot :list="list"/>
    </div>

    <button v-if="moreBtn" type="button" class="more-btn app-listing__more-btn">
      Показать еще

      <SvgIcon
        class="more-btn__arrow"
        name="arrow_down"
        width="62"
        height="92"
      />
    </button>

    <a 
   v-else-if="moreLink" href="#" class="app-listing__link link">Смотреть все</a>
  </section>
</template>

<script setup>
  const props = defineProps({
    title: {
      type: String,
      default: "",
    },
    url: {
      type: String,
      default: "",
      required: true
    },
    moreBtn: {
      type: Boolean,
      default: false
    },
      moreLink: {
      type: Boolean,
      default: false
    },
    grid: {
      type: String,
      default: "row",
    },
  });

  const listClass = computed(() => props.grid ==="column" ? "app-listing__column-list" : "app-listing__list")

  const list = ref([]);

    const { data } = props.url ? await useAsyncData(`list-${props.url}`, () => {
    return $fetch(props.url);
  }) : { data: null };

  if (data?.value) list.value = data.value;
</script>

<style lang="less">
.app-listing {
  .container;
    display: flex;
    flex-direction: column;

    &__column-list {
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    &__list {
      display: flex;
      flex-wrap: wrap;
      margin: 0 -30px -120px;
      @media @bw1660 {
        margin: 0 -20px -100px;
      }
      @media @bw1340 {
        margin: 0 -15px -100px;
      }
      @media @bw1020 {
        justify-content: center;
        margin: 0 -15px -80px;
      }
      @media @bw768 {
        margin: 0 -10px -80px;
      }
      @media @bw650 {
        margin: 0 0 -60px;
      }
    }
    &__card {
      width: calc(33.3333% - 60px); 
      margin: 0 30px 120px;
      @media @bw1660 {
        width: calc(33.3333% - 48px);
        margin: 0 20px 100px;
      }
      @media @bw1340 {
        width: calc(33.3333% - 30px); 
        margin: 0 15px 100px;
      }
      @media @bw1020 {
        width: calc(50% - 30px); 
        max-width: 405px;
        margin: 0 15px 80px;
      }
    }
    &__more-btn {
      align-self: center;
      margin-top: 120px;
    }
    &__link {
    display: block;
    margin-top: 100px;
    margin-left: auto;
    margin-right: 75px;
    }
}
</style>